# RFC 9113 Appendix A: Prohibited cipher suites for HTTP/2 over TLS 1.2
PROHIBITED_CIPHER_SUITES = [
    0x0001,  # TLS_RSA_WITH_NULL_MD5
    0x0002,  # TLS_RSA_WITH_NULL_SHA
    0x0005,  # TLS_RSA_WITH_RC4_128_MD5
    0x000A,  # TLS_RSA_WITH_DES_CBC_SHA
    0x002F,  # TLS_RSA_WITH_AES_128_CBC_SHA
    0x0035,  # TLS_RSA_WITH_AES_256_CBC_SHA
    0x003C,  # TLS_RSA_WITH_AES_128_CBC_SHA256
    0x003D,  # TLS_RSA_WITH_AES_256_CBC_SHA256
    # Add more prohibited suites as needed
]

# Strong cipher suites that should be preferred
STRONG_CIPHER_SUITES = [
    0xC02F,  # TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256
    0xC030,  # TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384
    0xCCA9,  # TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256
]

def parse_tls_record(data):
    """Parse a TLS record layer message."""
    if len(data) < 5:
        return None, None, None
    
    content_type = data[0]
    version = struct.unpack('!H', data[1:3])[0]
    length = struct.unpack('!H', data[3:5])[0]
    payload = data[5:5+length]
    
    return content_type, version, payload

def parse_client_hello(payload):
    """Parse a TLS ClientHello message."""
    if len(payload) < 43:
        return None
    
    # Parse basic ClientHello fields
    version = struct.unpack('!H', payload[1:3])[0]
    random = payload[3:39]
    session_id_len = payload[39]
    session_id = payload[40:40+session_id_len]
    
    # Parse cipher suites
    cipher_suites_len = struct.unpack('!H', payload[40+session_id_len:42+session_id_len])[0]
    cipher_suites = []
    offset = 42 + session_id_len
    for i in range(0, cipher_suites_len, 2):
        cipher_suites.append(struct.unpack('!H', payload[offset+i:offset+i+2])[0])
    
    return {
        'version': version,
        'random': random,
        'session_id': session_id,
        'cipher_suites': cipher_suites
    }

def craft_downgraded_client_hello(original_hello, target_cipher):
    """Create a modified ClientHello with a weak cipher suite."""
    # Start with the original message
    modified = bytearray(original_hello)
    
    # Find the cipher suites section and replace with our target
    offset = 42 + len(original_hello['session_id'])
    
    # Replace cipher suites length
    new_cipher_len = 2  # Just one cipher suite
    struct.pack_into('!H', modified, offset-2, new_cipher_len)
    
    # Replace the cipher suite
    struct.pack_into('!H', modified, offset, target_cipher)
    
    return bytes(modified)

def send_tls_record(sock, content_type, version, payload):
    """Send a TLS record."""
    record = struct.pack('!BBH', content_type, (version >> 8) & 0xFF, version & 0xFF)
    record += struct.pack('!H', len(payload))
    record += payload
    sock.sendall(record)

def receive_tls_record(sock, timeout=5):
    """Receive a TLS record."""
    sock.settimeout(timeout)
    header = sock.recv(5)
    if len(header) < 5:
        return None, None, None
    
    content_type = header[0]
    version = struct.unpack('!H', header[1:3])[0]
    length = struct.unpack('!H', header[3:5])[0]
    
    payload = b''
    while len(payload) < length:
        chunk = sock.recv(length - len(payload))
        if not chunk:
            break
        payload += chunk
    
    return content_type, version, payload

