        weak_cipher = 0x002F
        
        # Craft a minimal ClientHello
        client_hello = bytearray()
        client_hello += struct.pack('!B', 0x01)  # Handshake type: ClientHello
        client_hello += struct.pack('!I', 0)[1:]  # Length (will be updated)
        client_hello += struct.pack('!H', 0x0303)  # TLS 1.2 version
        client_hello += os.urandom(32)  # Random bytes
        client_hello += struct.pack('!B', 0)  # Session ID length
        client_hello += struct.pack('!H', 2)  # Cipher suites length
        client_hello += struct.pack('!H', weak_cipher)  # Weak cipher suite
        client_hello += struct.pack('!B', 1)  # Compression methods length
        client_hello += struct.pack('!B', 0)  # Null compression
        
        # Update length
        client_hello[1:4] = struct.pack('!I', len(client_hello) - 4)[1:]
        
        # Send the crafted ClientHello
        send_tls_record(sock, 0x16, 0x0303, bytes(client_hello))
        print(f"[*] Sent ClientHello with weak cipher suite: 0x{weak_cipher:04X}")
        
        # Receive server response
        content_type, version, payload = receive_tls_record(sock)
        
        if content_type == 0x15:  # Alert
            alert_level = payload[0]
